seq = open("region.fasta").read().split("\n", 1)[1].replace("\n", "").strip()

def orfs(s, minlen=150):
    stops3 = {"TAA","TAG","TGA"}
    res = []
    # frames: +1,+2,+3,+4,+5,+6 (negative frames reversed)
    for strand in ("+","-"):
        ss = s if strand=="+" else s[::-1].translate(str.maketrans("ACGT","TGCA"))
        for f in range(3):
            i = f
            start = None
            while i <= len(ss)-3:
                cod = ss[i:i+3]
                if start is None and cod == "ATG":
                    start = i
                    i += 3
                elif start is not None and cod in stops3:
                    L = i+3 - start
                    if L >= minlen:
                        fwd = start if strand=="+" else len(s) - (i+3) + 1  # 1-based start in original (approx)
                        res.append((strand, f, start if strand=="+" else None, L, ss[start:i+3]))
                    start = None
                    i += 3
                else:
                    i += 3
    return res

r = orfs(seq, 200)
r.sort(key=lambda x: -x[3])
print("ORFs >= 200 nt (from a given ATG):")
for strand,f,start,L,seqd in r:
    if strand=="+":
        print(f"+ frame{f+1}  start={start+1}  end={start+L}  len={L}")
    else:
        print(f"- frame{(f)}  len={L} (coords in revcomp: {start+1}-{start+L})")
