import urllib.request, socket
socket.setdefaulttimeout(15)

def try_url(url, data=None, headers=None):
    try:
        req = urllib.request.Request(url, data=data, headers=headers or {})
        with urllib.request.urlopen(req) as r:
            return r.status, r.read()
    except Exception as e:
        return None, f"{type(e).__name__}: {str(e)[:120]}"

for u in [
  "http://rest.ensembl.org/info/ping?content-type=application/json",
  "http://www.ebi.ac.uk/Tools/services/rest/ncbiblast/parameters",
  "http://www.rcsb.org/pdb/rest/search",
  "http://togo-id.uc.jp/togo/id/convert/uniprot_to_pdb",
]:
    s, b = try_url(u)
    print(u, "->", s, (b[:120] if s else b))
