import urllib.request, json, socket
socket.setdefaulttimeout(10)
BASE = "http://www.ebi.ac.uk/Tools/services/rest/ncbiblast"
rids = json.load(open("ebi_rids.json"))
status = {}
for name, jid in rids.items():
    try:
        with urllib.request.urlopen(f"{BASE}/status/{jid}") as r:
            status[name] = r.read().decode().strip()
    except Exception as e:
        status[name] = f"ERR {type(e).__name__}"
json.dump(status, open("ebi_status.json","w"))
print(status)
"}

